// 讀取 payload
var data = msg.payload;

// 修改 payload
msg.payload = "新的內容";

// 新增自訂屬性
msg.myData = { value: 100 };

// 回傳訊息
return msg;

// 回傳到第一個輸出
return msg;

// 回傳到多個輸出
return [msg1, msg2, msg3];

// 某些輸出不送出（null）
return [msg, null, msg3];

// 使用 node.send() 和 node.done()
setTimeout(function() {
    msg.payload = "延遲的訊息";
    node.send(msg);
    node.done();
}, 2000);

// 儲存到 flow context
flow.set('temperature', 25.5);

// 讀取 flow context
var temp = flow.get('temperature');

// 儲存到 global context
global.set('systemStatus', 'running');

// 讀取 global context
var status = global.get('systemStatus');

msg.payload = { temp: temp, status: status };
return msg;

